-- ============================================================
-- 表：pbl_references  参考文献（60条）
-- ============================================================

DROP TABLE IF EXISTS `pbl_references`;

CREATE TABLE `pbl_references` (
  `id` int NOT NULL AUTO_INCREMENT,
  `seq` int NOT NULL COMMENT '顺序',
  `type` varchar(50) DEFAULT NULL COMMENT '类型',
  `author` text COMMENT '作者',
  `year` int DEFAULT NULL COMMENT '年份',
  `title` text COMMENT '名称',
  `title_zh` text COMMENT '中文标题',
  `source` text COMMENT '出处',
  `link` text COMMENT '链接原始值',
  `notes` text COMMENT '备注',
  `link_type` varchar(20) DEFAULT NULL COMMENT 'url/pdf/text/null',
  `local_file` varchar(255) DEFAULT NULL COMMENT '本地保存文件名',
  `download_status` varchar(50) DEFAULT NULL COMMENT '下载状态',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=61 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='参考文献';

